/**
 * Tests for the address and transaction-signature validators.
 *
 * These two validators are the gate every wallet-facing route runs through, and
 * they were the only part of the API layer that was *Cardano-specific* rather
 * than merely Cardano-named: the address rule required an `addr1…` prefix and
 * the hash rule required 64 hex characters, so a Solana key or signature was
 * rejected with a 400 before any route logic ran.
 *
 * The positive cases use real base58 keys generated by web3.js, so the length
 * and alphabet bounds are exercised against actual output rather than a
 * hand-written string that might drift from what a wallet sends.
 */
import { Keypair } from "@solana/web3.js";
import { assert } from "chai";

import { encodeBase58 } from "@workspace/solana-escrow";
import { cardanoAddress, txHash } from "../src/validation";

describe("cardanoAddress (now a Solana public key)", () => {
  it("accepts a freshly generated Solana public key", () => {
    for (let i = 0; i < 5; i++) {
      const key = Keypair.generate().publicKey.toBase58();
      assert.equal(cardanoAddress.parse(key), key, key);
    }
  });

  it("accepts the all-zeros system address", () => {
    assert.equal(
      cardanoAddress.parse("11111111111111111111111111111111"),
      "11111111111111111111111111111111"
    );
  });

  it("rejects a Cardano bech32 address", () => {
    // The exact input the old validator was written for, and the one that must
    // now fail: leaving it accepted would let a Cardano address reach a route
    // that builds a Solana `PublicKey` from it.
    assert.throws(() => cardanoAddress.parse("addr1qxtz8jnhv4f5us5q9a3d4e6r7t8y"));
  });

  it("rejects base58 containing characters outside the alphabet", () => {
    // '0', 'O', 'I' and 'l' are excluded from base58 precisely to avoid
    // transcription ambiguity; a key containing them is not a Solana key.
    assert.throws(() =>
      cardanoAddress.parse("0OIl0OIl0OIl0OIl0OIl0OIl0OIl0OIl0OIl")
    );
  });

  it("rejects a key that is too short", () => {
    assert.throws(() => cardanoAddress.parse("1111111111"));
  });

  it("rejects a key that is too long", () => {
    assert.throws(() => cardanoAddress.parse("1".repeat(45)));
  });

  it("trims surrounding whitespace, as the old validator did", () => {
    const key = Keypair.generate().publicKey.toBase58();
    assert.equal(cardanoAddress.parse(`  ${key}  `), key);
  });
});

describe("txHash (now a Solana transaction signature)", () => {
  it("accepts a 64-byte base58 value, as a wallet signature is", () => {
    // A Solana signature is 64 raw bytes; the transport encodes them to base58.
    const signature = encodeBase58(new Uint8Array(64).fill(7));
    assert.equal(txHash.parse(signature), signature);
  });

  it("rejects a 64-character hex string", () => {
    // The old shape — 64 hex characters — is not the base58 form the backend
    // is handed, and it must not slip through on length alone.
    assert.throws(() => txHash.parse("a".repeat(64)));
  });

  it("rejects a signature that is too short", () => {
    assert.throws(() => txHash.parse("1".repeat(63)));
  });

  it("rejects a signature containing non-base58 characters", () => {
    assert.throws(() => txHash.parse(`${"0".repeat(63)}x`));
  });
});
